screenPanels.initJs:
function(container, apiUrl, tables) {
  let currentEditId = null;

  // 生徒データとの結合用
  const studentMap = new Map();
  if (tables[0]) {
    tables[0].records.forEach(student => {
      studentMap.set(student.生徒ID, student);
    });
  }

  // 生徒選択ドロップダウンの初期化
  function initStudentSelect() {
    const select = container.querySelector('#select-student');
    select.innerHTML = '<option value="">生徒を選択してください</option>';

    if (tables[0]) {
      tables[0].records.filter(s => s.在籍状況).forEach(student => {
        const option = document.createElement('option');
        option.value = student.生徒ID;
        option.textContent = `${student.生徒氏名} (${student.学年}年生)`;
        select.appendChild(option);
      });
    }
  }

  // 学年表示用関数
  function getGradeText(grade) {
    if (grade === 0) return '幼稚園';
    if (grade <= 6) return `${grade}年生`;
    if (grade <= 9) return `中${grade - 6}年`;
    return `${grade}年`;
  }

  // 未納日数計算
  function getUnpaidDays(targetMonth, isPaid) {
    if (isPaid) return 0;
    const targetDate = new Date(targetMonth + '-01');
    const today = new Date();
    const diffTime = today - targetDate;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return Math.max(0, diffDays);
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#fee-table-body');
    tbody.innerHTML = rows.map(row => {
      const student = studentMap.get(row.生徒ID);
      const studentName = student ? student.生徒氏名 : '不明';
      const grade = student ? getGradeText(student.学年) : '-';
      const isPaid = row.支払済フラグ;
      const statusBadge = isPaid 
        ? '<span style="background: #27ae60; color: #d0e4ff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">入金済</span>'
        : '<span style="background: #e74c3c; color: #d0e4ff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">未納</span>';
      const paymentDate = row.支払日時 ? new Date(row.支払日時).toLocaleDateString('ja-JP') : '-';
      const unpaidDays = getUnpaidDays(row.対象年月, isPaid);

      return `
        <tr data-id="${row.月謝ID}">
          <td style="color: var(--text);">${studentName}</td>
          <td style="color: var(--text);">${grade}</td>
          <td style="color: var(--text);">${row.対象年月}</td>
          <td style="color: var(--text);">¥${(row.月謝金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
          <td style="color: var(--text);">${paymentDate}</td>
          <td style="color: var(--text);">${unpaidDays > 0 ? unpaidDays + '日' : '-'}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${row.月謝ID}">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${row.月謝ID}">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // KPI更新
  function updateKPIs(rows) {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const lastMonth = new Date(new Date().setMonth(new Date().getMonth() - 1)).toISOString().slice(0, 7);

    const currentMonthRows = rows.filter(r => r.対象年月 === currentMonth);
    const lastMonthRows = rows.filter(r => r.対象年月 === lastMonth);

    const monthlyIncome = currentMonthRows.filter(r => r.支払済フラグ).reduce((sum, r) => sum + (r.月謝金額 || 0), 0);
    const lastMonthIncome = lastMonthRows.filter(r => r.支払済フラグ).reduce((sum, r) => sum + (r.月謝金額 || 0), 0);
    const unpaidCount = currentMonthRows.filter(r => !r.支払済フラグ).length;
    const paidCount = currentMonthRows.filter(r => r.支払済フラグ).length;
    const avgFee = rows.length > 0 ? Math.round(rows.reduce((sum, r) => sum + (r.月謝金額 || 0), 0) / rows.length) : 0;

    const changePercent = lastMonthIncome > 0 ? Math.round(((monthlyIncome - lastMonthIncome) / lastMonthIncome) * 100) : 0;
    const changeText = changePercent > 0 ? `+${changePercent}%` : `${changePercent}%`;

    container.querySelector('#kpi-monthly-income').textContent = `¥${monthlyIncome.toLocaleString()}`;
    container.querySelector('#kpi-monthly-change').textContent = `前月比 ${changeText}`;
    container.querySelector('#kpi-unpaid-count').textContent = `${unpaidCount}件`;
    container.querySelector('#kpi-paid-count').textContent = `${paidCount}件`;
    container.querySelector('#kpi-avg-fee').textContent = `¥${avgFee.toLocaleString()}`;
  }

  // グラフ初期化
  function initCharts(rows) {
    // 月別収入推移グラフ
    const monthlyData = {};
    rows.filter(r => r.支払済フラグ).forEach(row => {
      const month = row.対象年月;
      monthlyData[month] = (monthlyData[month] || 0) + (row.月謝金額 || 0);
    });

    const sortedMonths = Object.keys(monthlyData).sort();
    const incomeData = sortedMonths.map(month => monthlyData[month]);

    const incomeCtx = container.querySelector('#income-chart').getContext('2d');
    new Chart(incomeCtx, {
      type: 'line',
      data: {
        labels: sortedMonths,
        datasets: [{
          label: '月別収入',
          data: incomeData,
          borderColor: '#3498db',
          backgroundColor: 'rgba(52, 152, 219, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });

    // 支払い状況円グラフ
    const paidCount = rows.filter(r => r.支払済フラグ).length;
    const unpaidCount = rows.filter(r => !r.支払済フラグ).length;

    const statusCtx = container.querySelector('#payment-status-chart').getContext('2d');
    new Chart(statusCtx, {
      type: 'doughnut',
      data: {
        labels: ['入金済', '未納'],
        datasets: [{
          data: [paidCount, unpaidCount],
          backgroundColor: ['#27ae60', '#e74c3c']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false
      }
    });
  }

  // 初期データ読み込みと描画
  window.aivicApi.list(2).then(rows => {
    if (rows) {
      renderRows(rows);
      updateKPIs(rows);
      initCharts(rows);
    }
  });

  // 生徒選択ドロップダウン初期化
  initStudentSelect();

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const grade = container.querySelector('#select-grade').value;
    const targetMonth = container.querySelector('#input-target-month').value;
    const paymentStatus = container.querySelector('#select-payment-status').value;

    const rows = await window.aivicApi.list(2);
    if (!rows) return;

    const filtered = rows.filter(row => {
      const student = studentMap.get(row.生徒ID);
      const matchKeyword = !keyword || (student && student.生徒氏名.toLowerCase().includes(keyword));
      const matchGrade = !grade || (student && student.学年.toString() === grade);
      const matchMonth = !targetMonth || row.対象年月 === targetMonth;
      const matchStatus = !paymentStatus || 
        (paymentStatus === 'paid' && row.支払済フラグ) ||
        (paymentStatus === 'unpaid' && !row.支払済フラグ);

      return matchKeyword && matchGrade && matchMonth && matchStatus;
    });

    renderRows(filtered);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(2);
    if (!rows) return;

    const headers = ['生徒名', '学年', '対象年月', '月謝金額', '支払い状況', '支払日', '未納日数'];
    const csvData = [headers.join(',')];

    rows.forEach(row => {
      const student = studentMap.get(row.生徒ID);
      const studentName = student ? student.生徒氏名 : '不明';
      const grade = student ? getGradeText(student.学年) : '-';
      const status = row.支払済フラグ ? '入金済' : '未納';
      const paymentDate = row.支払日時 ? new Date(row.支払日時).toLocaleDateString('ja-JP') : '';
      const unpaidDays = getUnpaidDays(row.対象年月, row.支払済フラグ);

      csvData.push([
        studentName,
        grade,
        row.対象年月,
        row.月謝金額 || 0,
        status,
        paymentDate,
        unpaidDays > 0 ? unpaidDays + '日' : ''
      ].join(','));
    });

    const csvContent = '\uFEFF' + csvData.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '月謝管理_' + new Date().toISOString().slice(0, 10) + '.csv';
    link.click();
  });

  // 登録機能
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const studentId = container.querySelector('#select-student').value;
    const targetMonth = container.querySelector('#input-fee-month').value;
    const amount = parseInt(container.querySelector('#input-fee-amount').value);
    const paymentDate = container.querySelector('#input-payment-date').value;
    const isPaid = container.querySelector('input[name="payment-status"]:checked').value === 'true';

    if (!studentId || !targetMonth || !amount) {
      alert('必須項目を入力してください');
      return;
    }

    const data = {
      生徒ID: studentId,
      対象年月: targetMonth,
      月謝金額: amount,
      支払済フラグ: isPaid,
      支払日時: paymentDate ? new Date(paymentDate).toISOString() : null
    };

    const saved = await window.aivicApi.save(2, data);
    if (saved) {
      const rows = await window.aivicApi.list(2);
      if (rows) {
        renderRows(rows);
        updateKPIs(rows);
        initCharts(rows);
      }

      // フォームリセット
      container.querySelector('#select-student').value = '';
      container.querySelector('#input-fee-month').value = '';
      container.querySelector('#input-fee-amount').value = '';
      container.querySelector('#input-payment-date').value = '';
      container.querySelector('input[name="payment-status"][value="false"]').checked = true;
      container.querySelector('#input-memo').value = '';
    }
  });

  // 更新機能
  container.querySelector('#btn-update').addEventListener('click', async () => {
    if (!currentEditId) return;

    const studentId = container.querySelector('#select-student').value;
    const targetMonth = container.querySelector('#input-fee-month').value;
    const amount = parseInt(container.querySelector('#input-fee-amount').value);
    const paymentDate = container.querySelector('#input-payment-date').value;
    const isPaid = container.querySelector('input[name="payment-status"]:checked').value === 'true';

    if (!studentId || !targetMonth || !amount) {
      alert('必須項目を入力してください');
      return;
    }

    const data = {
      生徒ID: studentId,
      対象年月: targetMonth,
      月謝金額: amount,
      支払済フラグ: isPaid,
      支払日時: paymentDate ? new Date(paymentDate).toISOString() : null
    };

    const updated = await window.aivicApi.update(2, currentEditId, data);
    if (updated) {
      const rows = await window.aivicApi.list(2);
      if (rows) {
        renderRows(rows);
        updateKPIs(rows);
        initCharts(rows);
      }

      // 編集モード終了
      currentEditId = null;
      container.querySelector('#btn-save').style.display = 'inline-block';
      container.querySelector('#btn-update').style.display = 'none';
      container.querySelector('#btn-cancel').style.display = 'none';

      // フォームリセット
      container.querySelector('#select-student').value = '';
      container.querySelector('#input-fee-month').value = '';
      container.querySelector('#input-fee-amount').value = '';
      container.querySelector('#input-payment-date').value = '';
      container.querySelector('input[name="payment-status"][value="false"]').checked = true;
      container.querySelector('#input-memo').value = '';
    }
  });

  // キャンセル機能
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    currentEditId = null;
    container.querySelector('#btn-save').style.display = 'inline-block';
    container.querySelector('#btn-update').style.display = 'none';
    container.querySelector('#btn-cancel').style.display = 'none';

    // フォームリセット
    container.querySelector('#select-student').value = '';
    container.querySelector('#input-fee-month').value = '';
    container.querySelector('#input-fee-amount').value = '';
    container.querySelector('#input-payment-date').value = '';
    container.querySelector('input[name="payment-status"][value="false"]').checked = true;
    container.querySelector('#input-memo').value = '';
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    // 削除処理
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この月謝情報を削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(2, id);

      const rows = await window.aivicApi.list(2);
      if (rows) {
        renderRows(rows);
        updateKPIs(rows);
        initCharts(rows);
      }
      return;
    }

    // 編集処理
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(2);
      if (!rows) return;

      const row = rows.find(r => r.月謝ID === id);
      if (!row) return;

      // フォームに値を設定
      container.querySelector('#select-student').value = row.生徒ID;
      container.querySelector('#input-fee-month').value = row.対象年月;
      container.querySelector('#input-fee-amount').value = row.月謝金額;
      if (row.支払日時) {
        container.querySelector('#input-payment-date').value = new Date(row.支払日時).toISOString().slice(0, 10);
      }
      container.querySelector(`input[name="payment-status"][value="${row.支払済フラグ}"]`).checked = true;

      // 編集モードに切り替え
      currentEditId = id;
      container.querySelector('#btn-save').style.display = 'none';
      container.querySelector('#btn-update').style.display = 'inline-block';
      container.querySelector('#btn-cancel').style.display = 'inline-block';
    }
  });
}

function(container, apiUrl, tables) {
  let currentStudents = [];
  let selectedStudentId = null;

  // 今日の日付を初期値に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#input-class-date').value = today;

  // 出席履歴再描画関数
  function renderAttendanceHistory(records) {
    const tbody = container.querySelector('#history-tbody');
    tbody.innerHTML = records.map(record => `
      <tr data-id="${record.id}">
        <td>${new Date(record.授業日).toLocaleDateString()}</td>
        <td>${record.生徒名 || ''}</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; 
            background: ${record.出席状況 === '出席' ? '#22c55e' : record.出席状況 === '欠席' ? '#ef4444' : '#f59e0b'}; 
            color: #ffffff;">
            ${record.出席状況}
          </span>
        </td>
        <td>${record.振替フラグ ? '振替' : ''}</td>
        <td>${record.備考 || ''}</td>
        <td>
          <button class="action-btn secondary delete-attendance-btn" data-id="${record.id}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 生徒一覧再描画関数
  function renderStudents(students) {
    const tbody = container.querySelector('#students-tbody');
    currentStudents = students;

    tbody.innerHTML = students.map(student => `
      <tr data-id="${student.id}">
        <td>${student.生徒氏名}</td>
        <td>${student.学年}年生</td>
        <td>
          <select class="input attendance-select" data-student-id="${student.id}" style="width: 120px;">
            <option value="">選択</option>
            <option value="出席">出席</option>
            <option value="欠席">欠席</option>
            <option value="遅刻">遅刻</option>
            <option value="早退">早退</option>
          </select>
        </td>
        <td>
          <input type="text" class="input absence-reason" data-student-id="${student.id}" 
                 placeholder="欠席理由" style="width: 150px;">
        </td>
        <td>
          <button class="action-btn secondary makeup-btn" data-student-id="${student.id}">振替設定</button>
        </td>
        <td>
          <button class="action-btn secondary history-btn" data-student-id="${student.id}">履歴</button>
        </td>
      </tr>
    `).join('');

    updateAttendanceStats();
  }

  // 出席統計更新
  function updateAttendanceStats() {
    const selects = container.querySelectorAll('.attendance-select');
    const total = selects.length;
    let present = 0;
    let absent = 0;

    selects.forEach(select => {
      if (select.value === '出席') present++;
      if (select.value === '欠席') absent++;
    });

    const rate = total > 0 ? Math.round((present / total) * 100) : 0;

    container.querySelector('#total-students').textContent = total;
    container.querySelector('#present-count').textContent = present;
    container.querySelector('#absent-count').textContent = absent;
    container.querySelector('#attendance-rate').textContent = rate + '%';
  }

  // 初期データ表示
  async function loadInitialData() {
    const students = await window.aivicApi.list(0);
    if (students) {
      const activeStudents = students.filter(s => s.在籍状況);
      renderStudents(activeStudents);
    }

    const attendanceRecords = await window.aivicApi.list(3);
    if (attendanceRecords) {
      // 生徒名を結合
      const studentsMap = new Map((students || []).map(s => [s.id, s.生徒氏名]));
      const enrichedRecords = attendanceRecords.map(record => ({
        ...record,
        生徒名: studentsMap.get(record.生徒ID) || '不明'
      }));
      renderAttendanceHistory(enrichedRecords);
    }
  }

  // ナビゲーション
  container.querySelector('#btn-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1778135812549');
  });

  container.querySelector('#btn-tuition').addEventListener('click', () => {
    window.showScreen('scr-1778135743407');
  });

  container.querySelector('#btn-parent-contact').addEventListener('click', () => {
    window.showScreen('scr-1778135802323');
  });

  // 生徒一覧読み込み
  container.querySelector('#btn-load-students').addEventListener('click', async () => {
    const students = await window.aivicApi.list(0);
    if (students) {
      const activeStudents = students.filter(s => s.在籍状況);
      renderStudents(activeStudents);
    }
  });

  // 検索機能
  container.querySelector('#input-search').addEventListener('input', (e) => {
    const keyword = e.target.value.toLowerCase();
    const filtered = currentStudents.filter(student => 
      student.生徒氏名.toLowerCase().includes(keyword)
    );
    renderStudents(filtered);
  });

  // 一括出席登録
  container.querySelector('#btn-bulk-present').addEventListener('click', () => {
    const selects = container.querySelectorAll('.attendance-select');
    selects.forEach(select => {
      select.value = '出席';
    });
    updateAttendanceStats();
  });

  // 出席データ保存
  container.querySelector('#btn-save-attendance').addEventListener('click', async () => {
    const classDate = container.querySelector('#input-class-date').value;
    if (!classDate) {
      alert('授業日を選択してください');
      return;
    }

    const selects = container.querySelectorAll('.attendance-select');
    const savePromises = [];

    selects.forEach(select => {
      if (select.value) {
        const studentId = select.dataset.studentId;
        const reasonInput = container.querySelector(`input.absence-reason[data-student-id="${studentId}"]`);
        const reason = reasonInput ? reasonInput.value : '';

        const attendanceData = {
          生徒ID: studentId,
          授業日: new Date(classDate).toISOString(),
          出席状況: select.value,
          振替フラグ: false,
          備考: reason
        };

        savePromises.push(window.aivicApi.save(3, attendanceData));
      }
    });

    if (savePromises.length === 0) {
      alert('出席状況が選択されていません');
      return;
    }

    try {
      await Promise.all(savePromises);
      alert('出席データを保存しました');
      loadInitialData(); // 履歴を再読み込み
    } catch (error) {
      alert('保存に失敗しました');
    }
  });

  // 出席履歴表示切り替え
  container.querySelector('#btn-attendance-history').addEventListener('click', () => {
    const historyArea = container.querySelector('#history-area');
    historyArea.classList.toggle('hidden');
  });

  // 保護者通知送信
  container.querySelector('#btn-send-notification').addEventListener('click', () => {
    alert('保護者通知機能は開発中です');
  });

  // 出席状況変更時の統計更新
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('attendance-select')) {
      updateAttendanceStats();
    }
  });

  // 振替設定モーダル
  container.addEventListener('click', (e) => {
    const makeupBtn = e.target.closest('.makeup-btn');
    if (makeupBtn) {
      selectedStudentId = makeupBtn.dataset.studentId;
      container.querySelector('#makeup-modal').classList.remove('hidden');
    }

    const historyBtn = e.target.closest('.history-btn');
    if (historyBtn) {
      const studentId = historyBtn.dataset.studentId;
      // 特定生徒の履歴表示（簡易実装）
      alert(`生徒ID: ${studentId} の履歴表示機能は開発中です`);
    }

    const deleteBtn = e.target.closest('.delete-attendance-btn');
    if (deleteBtn) {
      if (confirm('この出席記録を削除しますか？')) {
        window.aivicApi.delete(3, deleteBtn.dataset.id).then(() => {
          loadInitialData();
        });
      }
    }
  });

  // モーダル操作
  container.querySelector('#btn-cancel-makeup').addEventListener('click', () => {
    container.querySelector('#makeup-modal').classList.add('hidden');
  });

  container.querySelector('#btn-save-makeup').addEventListener('click', async () => {
    const makeupDate = container.querySelector('#makeup-date').value;
    const makeupNote = container.querySelector('#makeup-note').value;

    if (!makeupDate) {
      alert('振替日を選択してください');
      return;
    }

    const makeupData = {
      生徒ID: selectedStudentId,
      授業日: new Date(makeupDate).toISOString(),
      出席状況: '出席',
      振替フラグ: true,
      備考: makeupNote
    };

    const saved = await window.aivicApi.save(3, makeupData);
    if (saved) {
      alert('振替授業を設定しました');
      container.querySelector('#makeup-modal').classList.add('hidden');
      loadInitialData();
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
