function(container, apiUrl, tables) {
  // ナビゲーションボタンのイベントリスナー
  container.querySelector("#btn-tuition").addEventListener("click", () => {
    window.showScreen("scr-1778135743407");
  });

  container.querySelector("#btn-attendance").addEventListener("click", () => {
    window.showScreen("scr-1778135778537");
  });

  container.querySelector("#btn-contact").addEventListener("click", () => {
    window.showScreen("scr-1778135802323");
  });

  // データ読み込みと表示更新
  async function loadDashboardData() {
    try {
      const [students, guardians, tuitions, attendances] = await Promise.all([
        window.aivicApi.list(0), // 生徒マスタ
        window.aivicApi.list(1), // 保護者マスタ
        window.aivicApi.list(2), // 月謝管理
        window.aivicApi.list(3)  // 出席管理
      ]);

      if (!students || !tuitions || !attendances) {
        console.error("データの読み込みに失敗しました");
        return;
      }

      updateDashboard(students, guardians, tuitions, attendances);
    } catch (error) {
      console.error("ダッシュボードデータの読み込みエラー:", error);
    }
  }

  function updateDashboard(students, guardians, tuitions, attendances) {
    const today = new Date().toISOString().split('T')[0];
    const currentMonth = new Date().toISOString().slice(0, 7); // YYYY-MM

    // 本日の出席状況
    const todayAttendances = attendances.filter(a => 
      a.授業日 && a.授業日.startsWith(today)
    );

    const presentCount = todayAttendances.filter(a => a.出席状況 === '出席').length;
    const absentCount = todayAttendances.filter(a => a.出席状況 === '欠席').length;
    const lateCount = todayAttendances.filter(a => a.出席状況 === '遅刻').length;

    container.querySelector("#today-present").textContent = presentCount;
    container.querySelector("#today-absent").textContent = absentCount;
    container.querySelector("#today-late").textContent = lateCount;

    // 今月の月謝収納状況
    const currentMonthTuitions = tuitions.filter(t => 
      t.対象年月 === currentMonth
    );

    const paidCount = currentMonthTuitions.filter(t => t.支払済フラグ).length;
    const unpaidCount = currentMonthTuitions.filter(t => !t.支払済フラグ).length;
    const totalCount = currentMonthTuitions.length;
    const paidRate = totalCount > 0 ? Math.round((paidCount / totalCount) * 100) : 0;

    container.querySelector("#tuition-paid").textContent = paidCount;
    container.querySelector("#tuition-unpaid").textContent = unpaidCount;
    container.querySelector("#tuition-rate").textContent = paidRate + "%";

    // 今月の入退会者数
    const activeStudents = students.filter(s => s.在籍状況);
    const newStudents = activeStudents.filter(s => 
      s.入会日 && s.入会日.startsWith(currentMonth)
    ).length;

    const withdrawnStudents = students.filter(s => 
      !s.在籍状況 && s.入会日 && s.入会日.startsWith(currentMonth)
    ).length;

    container.querySelector("#new-students").textContent = newStudents;
    container.querySelector("#withdrawn-students").textContent = withdrawnStudents;

    // 出席率ランキング
    updateAttendanceRanking(students, attendances);

    // 月謝未納者一覧
    updateUnpaidTuitionList(students, tuitions);

    // 未収金アラート
    updateUnpaidAlerts(students, tuitions);

    // 生徒数推移グラフ
    drawStudentChart(students);
  }

  function updateAttendanceRanking(students, attendances) {
    const activeStudents = students.filter(s => s.在籍状況);
    const rankings = [];

    activeStudents.forEach(student => {
      const studentAttendances = attendances.filter(a => a.生徒ID === student.生徒ID);
      const totalClasses = studentAttendances.length;
      const presentClasses = studentAttendances.filter(a => a.出席状況 === '出席').length;
      const attendanceRate = totalClasses > 0 ? Math.round((presentClasses / totalClasses) * 100) : 0;

      rankings.push({
        name: student.生徒氏名,
        rate: attendanceRate
      });
    });

    rankings.sort((a, b) => b.rate - a.rate);
    const top5 = rankings.slice(0, 5);

    const tbody = container.querySelector("#attendance-ranking");
    tbody.innerHTML = top5.map((item, index) => `
      <tr>
        <td>${index + 1}</td>
        <td>${item.name || ""}</td>
        <td>${item.rate}%</td>
      </tr>
    `).join("");
  }

  function updateUnpaidTuitionList(students, tuitions) {
    const unpaidList = [];

    students.filter(s => s.在籍状況).forEach(student => {
      const studentTuitions = tuitions.filter(t => 
        t.生徒ID === student.生徒ID && !t.支払済フラグ
      );

      if (studentTuitions.length > 0) {
        const totalAmount = studentTuitions.reduce((sum, t) => sum + (t.月謝金額 || 0), 0);
        unpaidList.push({
          name: student.生徒氏名,
          months: studentTuitions.length,
          amount: totalAmount
        });
      }
    });

    const tbody = container.querySelector("#unpaid-tuition");
    if (unpaidList.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" class="muted">未納者はありません</td></tr>';
    } else {
      tbody.innerHTML = unpaidList.map(item => `
        <tr>
          <td>${item.name || ""}</td>
          <td>${item.months}ヶ月</td>
          <td>¥${item.amount.toLocaleString()}</td>
        </tr>
      `).join("");
    }
  }

  function updateUnpaidAlerts(students, tuitions) {
    const alerts = [];

    students.filter(s => s.在籍状況).forEach(student => {
      const unpaidTuitions = tuitions.filter(t => 
        t.生徒ID === student.生徒ID && !t.支払済フラグ
      );

      if (unpaidTuitions.length >= 2) {
        alerts.push(`${student.生徒氏名}さん: ${unpaidTuitions.length}ヶ月未納`);
      }
    });

    const alertContainer = container.querySelector("#unpaid-alerts");
    if (alerts.length === 0) {
      alertContainer.innerHTML = '<div class="alert-item">未収金アラートはありません</div>';
    } else {
      alertContainer.innerHTML = alerts.map(alert => 
        `<div class="alert-item">${alert}</div>`
      ).join("");
    }
  }

  function drawStudentChart(students) {
    const canvas = container.querySelector("#student-chart");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;

    // 背景をクリア
    ctx.clearRect(0, 0, width, height);

    // 過去6ヶ月のデータを生成
    const months = [];
    const counts = [];

    for (let i = 5; i >= 0; i--) {
      const date = new Date();
      date.setMonth(date.getMonth() - i);
      const monthStr = date.toISOString().slice(0, 7);
      months.push(date.getMonth() + 1 + "月");

      // その月時点での在籍者数を計算
      const activeCount = students.filter(s => {
        const joinDate = new Date(s.入会日);
        return joinDate <= date && s.在籍状況;
      }).length;

      counts.push(activeCount);
    }

    // グラフ描画エリア
    const padding = 40;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    const maxCount = Math.max(...counts, 10);
    const stepX = chartWidth / (months.length - 1);
    const stepY = chartHeight / maxCount;

    // グリッド線
    ctx.strokeStyle = '#e0e6ed';
    ctx.lineWidth = 1;

    for (let i = 0; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(width - padding, y);
      ctx.stroke();
    }

    // データ線
    ctx.strokeStyle = '#3498db';
    ctx.lineWidth = 2;
    ctx.beginPath();

    counts.forEach((count, index) => {
      const x = padding + stepX * index;
      const y = height - padding - (count * stepY);

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });

    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#3498db';
    counts.forEach((count, index) => {
      const x = padding + stepX * index;
      const y = height - padding - (count * stepY);

      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });

    // ラベル
    ctx.fillStyle = '#64748b';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';

    months.forEach((month, index) => {
      const x = padding + stepX * index;
      ctx.fillText(month, x, height - 10);
    });
  }

  // 初期データ読み込み
  loadDashboardData();
}
